  if(state==='title'){/* attract handled in render */}
  else if(state==='stageIntro'){
    introTimer-=dt;
    if(introTimer<=0)beginStagePlay();
  }
  else if(state==='play'){
    stageTime+=dt;
    // spawn entry groups
    for(const g of entryQueue){
      if(!g.spawned&&stageTime>=g.start){
        g.spawned=true;
        g.members.forEach((m,i)=>{
          spawnEnemy(m.type,m.row,m.col,entryPath(m.row,m.col,g.side));
          // stagger via negative path time
          const e=enemies[enemies.length-1];
          e.t=-i*0.18;
